const menuButton=document.querySelector('.menu-button');const nav=document.querySelector('#nav');menuButton?.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')==='true';menuButton.setAttribute('aria-expanded',String(!open));nav.classList.toggle('open',!open);document.body.classList.toggle('menu-open',!open)});nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');document.body.classList.remove('menu-open');menuButton?.setAttribute('aria-expanded','false')}));
const tabs=[...document.querySelectorAll('[role="tab"]')];tabs.forEach(tab=>tab.addEventListener('click',()=>{tabs.forEach(t=>{const selected=t===tab;t.setAttribute('aria-selected',String(selected));document.getElementById(t.getAttribute('aria-controls')).hidden=!selected})}));
document.querySelectorAll('.service-select').forEach(link=>link.addEventListener('click',()=>{const select=document.querySelector('select[name="service"]');if(select)select.value=link.dataset.service}));
document.querySelector('#project-form')?.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);const subject=`Project inquiry: ${data.get('service')}`;const body=`Hello Nabura Labs,\n\nName: ${data.get('name')}\nWork email: ${data.get('email')}\nCompany: ${data.get('company')}\nEngagement: ${data.get('service')}\n\nProject context:\n${data.get('details')}\n\nThank you.`;window.location.href=`mailto:essam@naburalabs.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`});
document.querySelector('#year').textContent=new Date().getFullYear();
